import java.io.*;
import java.net.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import com.sun.net.httpserver.*;

public class ConfigService {
    private static final String AES_KEY_ENV = "CONFIG_AES_KEY";
    private static final String STORAGE_PATH = "/opt/configs/";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config", new ConfigHandler());
        server.createContext("/api/health", ex -> {
            ex.sendResponseHeaders(200, 2);
            ex.getResponseBody().write("ok".getBytes());
            ex.close();
        });
        server.start();
    }

    static class ConfigHandler implements HttpHandler {
        public void handle(HttpExchange ex) throws IOException {
            String method = ex.getRequestMethod();
            if ("GET".equals(method)) {
                handleGet(ex);
            } else if ("POST".equals(method)) {
                handlePost(ex);
            } else {
                ex.sendResponseHeaders(405, -1);
            }
        }

        private void handleGet(HttpExchange ex) throws IOException {
            Map<String, String> params = parseQuery(ex.getRequestURI().getQuery());
            String tenant = params.getOrDefault("tenant", "");
            String filename = params.getOrDefault("file", "default.conf");

            // Construct path - tenant isolation via directory
            String fullPath = STORAGE_PATH + tenant + "/" + filename;

            File target = new File(fullPath);
            if (!target.exists()) {
                ex.sendResponseHeaders(404, -1);
                return;
            }

            byte[] content = readFile(target);

            // Decrypt if encrypted marker present
            if (content.length > 4 && content[0] == 'E' && content[1] == 'N' && content[2] == 'C' && content[3] == ':') {
                try {
                    content = decryptContent(Arrays.copyOfRange(content, 4, content.length));
                } catch (Exception e) {
                    ex.sendResponseHeaders(500, -1);
                    return;
                }
            }

            ex.getResponseHeaders().set("Content-Type", "application/octet-stream");
            ex.getResponseHeaders().set("X-Tenant", tenant);
            ex.sendResponseHeaders(200, content.length);
            ex.getResponseBody().write(content);
            ex.close();
        }

        private void handlePost(HttpExchange ex) throws IOException {
            Map<String, String> params = parseQuery(ex.getRequestURI().getQuery());
            String tenant = params.getOrDefault("tenant", "");
            String filename = params.getOrDefault("file", "default.conf");

            byte[] body = ex.getRequestBody().readAllBytes();

            String fullPath = STORAGE_PATH + tenant + "/" + filename;
            File dir = new File(STORAGE_PATH + tenant);
            dir.mkdirs();

            try (FileOutputStream fos = new FileOutputStream(fullPath)) {
                fos.write(body);
            }

            ex.sendResponseHeaders(201, -1);
            ex.close();
        }

        private byte[] decryptContent(byte[] encrypted) throws Exception {
            String keyHex = System.getenv(AES_KEY_ENV);
            byte[] keyBytes = hexToBytes(keyHex);
            SecretKeySpec spec = new SecretKeySpec(keyBytes, "AES");
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, spec);
            return cipher.doFinal(encrypted);
        }

        private Map<String, String> parseQuery(String query) {
            Map<String, String> map = new HashMap<>();
            if (query == null) return map;
            for (String pair : query.split("&")) {
                String[] kv = pair.split("=", 2);
                if (kv.length == 2) {
                    map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                            URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
                }
            }
            return map;
        }

        private byte[] readFile(File f) throws IOException {
            try (FileInputStream fis = new FileInputStream(f)) {
                return fis.readAllBytes();
            }
        }

        private byte[] hexToBytes(String hex) {
            int len = hex.length();
            byte[] data = new byte[len / 2];
            for (int i = 0; i < len; i += 2) {
                data[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                        + Character.digit(hex.charAt(i + 1), 16));
            }
            return data;
        }
    }
}
